def is_valid_bst(node, lo, hi):
    if node is None:
        return True
    if node.val <= lo or node.val >= hi:
        return False
    return is_valid_bst(node.left, lo, node.val) and is_valid_bst(node.right, node.val, hi)

def subtree_sum(node):
    if node is None:
        return 0
    return node.val + subtree_sum(node.left) + subtree_sum(node.right)

def max_sum_bst_brute(root):
    best = 0
    def visit(node):
        nonlocal best
        if node is None:
            return
        if is_valid_bst(node, float('-inf'), float('inf')):        # re-validates from scratch every node
            best = max(best, subtree_sum(node))                        # re-sums from scratch every node
        visit(node.left)
        visit(node.right)
    visit(root)
    return best

