public class Main {
    static int best;

    static int maxSumBST(TreeNode root) {
        best = 0;
        dfs(root);
        return best;
    }

    // returns {isBst (0/1), min, max, sum}
    static long[] dfs(TreeNode node) {
        if (node == null) return new long[]{1, Long.MAX_VALUE, Long.MIN_VALUE, 0};   // sentinel
        long[] left = dfs(node.left);
        long[] right = dfs(node.right);
        if (left[0] == 1 && right[0] == 1 && left[2] < node.val && node.val < right[1]) {
            long total = left[3] + right[3] + node.val;
            best = (int) Math.max(best, total);                          // update running global best
            return new long[]{1, Math.min(left[1], node.val), Math.max(right[2], node.val), total};
        }
        return new long[]{0, 0, 0, 0};                                     // disqualified
    }
}

