int best;

// returns {isBst, min, max, sum}
tuple<bool,long long,long long,long long> dfs(TreeNode* node) {
    if (!node) return {true, LLONG_MAX, LLONG_MIN, 0};                    // sentinel
    auto [lIsBst, lMin, lMax, lSum] = dfs(node->left);
    auto [rIsBst, rMin, rMax, rSum] = dfs(node->right);
    if (lIsBst && rIsBst && lMax < node->val && node->val < rMin) {
        long long total = lSum + rSum + node->val;
        best = max((long long)best, total);                                 // update running global best
        return {true, min(lMin, (long long)node->val), max(rMax, (long long)node->val), total};
    }
    return {false, 0LL, 0LL, 0LL};                                        // disqualified
}

int maxSumBST(TreeNode* root) {
    best = 0;
    dfs(root);
    return best;
}
